import 'database.dart';

// Note: this imports database.dart (not just tables.dart) because the
// Companion types below (CatalogEntriesCompanion, etc.) are generated by
// drift as part of database.dart's `@DriftDatabase`/`part` pair, not
// tables.dart itself. database.dart imports this file right back for
// [seedCatalog]/[seedShoppingList] — that's a legal import cycle in Dart
// (unlike `part`/`part of`), since neither side has a circular *value*
// dependency, only type dependencies.

/// Phase 1 seed product catalog (EQ-A2 in docs/test-plan.md).
///
/// A small, hand-picked dataset standing in for the real shared
/// barcode/nutrition databases (ADR 0012/ADR 0013), which arrive in a
/// later phase. Barcodes are obviously-fake 12-digit test values, not real
/// UPCs — Phase 1 doesn't validate barcode checksums (that's ADR 0012
/// territory), so any distinct string works as a lookup key.
///
/// UREQS: SCAN-1, SYNC-1
final List<CatalogEntriesCompanion> seedCatalog = [
  _catalogEntry('100000000001', 'Whole Milk, 1 Gal', 'dairy'),
  _catalogEntry('100000000002', '2% Milk, 1 Gal', 'dairy'),
  _catalogEntry('100000000003', 'Chocolate Chip Cookies', 'snacks'),
  _catalogEntry('100000000004', 'Cheerios Cereal', 'cereal'),
  _catalogEntry('100000000005', 'Creamy Peanut Butter', 'pantry'),
  _catalogEntry('100000000006', 'Sourdough Bread', 'bakery'),
  _catalogEntry('100000000007', 'Large Eggs, Dozen', 'dairy'),
  _catalogEntry('100000000008', 'Salted Butter', 'dairy'),
  _catalogEntry('100000000009', 'Roma Tomatoes', 'produce'),
  _catalogEntry('100000000010', 'Yellow Onion', 'produce'),
  _catalogEntry('100000000011', 'Ground Coffee, Medium Roast', 'pantry'),
  _catalogEntry('100000000012', 'Orange Juice, 64oz', 'beverages'),
];

CatalogEntriesCompanion _catalogEntry(
  String barcode,
  String name,
  String category,
) {
  return CatalogEntriesCompanion.insert(
    barcode: barcode,
    name: name,
    category: category,
  );
}

/// Phase 1 seed shopping list, deliberately covering every matching path
/// the engine (LIST-2/LIST-3/LIST-6) needs to handle:
///
/// - "Milk" ties between two catalog entries → ambiguous match (LIST-3).
/// - "Choc Chip Cookies" only matches via synonym expansion (LIST-6).
/// - "Cheerios Cereal" matches a catalog entry exactly (LIST-2).
/// - "Fresh Basil" has no catalog entry at all → can only ever be resolved
///   by manual add (LIST-5), demonstrating scanning isn't the only path.
///
/// UREQS: LIST-2, LIST-3, LIST-5, LIST-6, SYNC-1
final List<ShoppingListItemsCompanion> seedShoppingList = [
  _listItem('Milk', 'dairy'),
  _listItem('Choc Chip Cookies', 'snacks'),
  _listItem('Cheerios Cereal', 'cereal'),
  _listItem('Fresh Basil', 'produce'),
];

ShoppingListItemsCompanion _listItem(String name, String category) {
  return ShoppingListItemsCompanion.insert(
    name: name,
    category: category,
    status: ListItemStatus.pending,
  );
}
